import type { CaseEvalReport, SuiteReport } from "./runEvalSuite.js";

const GENERATED_HEADER =
  "<!-- This file is generated by `npm run eval` / `npm run eval:flaky`. -->";

export function renderMarkdownReport(report: SuiteReport): string {
  const { summary } = report;
  const lines: string[] = [];

  lines.push(GENERATED_HEADER, "");
  lines.push(`# Eval Report — ${titleCase(report.mode)} mode`, "");
  lines.push(
    `**Model client**: \`${report.modelName}\`  `,
    `**Runs per case**: ${report.runsPerCase}  `,
    `**Total cases**: ${summary.totalCases}  `,
    `**Total runs**: ${summary.totalRuns}`,
    "",
  );

  lines.push("## Summary", "");
  lines.push("| Metric | Value |", "|---|---|");
  lines.push(`| outcome_pass_rate | ${pct(summary.outcomePassRate)} |`);
  lines.push(`| trajectory_pass_rate | ${pct(summary.trajectoryPassRate)} |`);
  lines.push(`| consistency_rate | ${pct(summary.consistencyRate)} |`);
  lines.push(`| escalation_precision | ${summary.escalation.precision.toFixed(4)} |`);
  lines.push(`| escalation_recall | ${summary.escalation.recall.toFixed(4)} |`);
  lines.push(`| average_simulated_cost | ${summary.costLatency.averageCostUnits} |`);
  lines.push(`| total_simulated_cost | ${summary.costLatency.totalCostUnits} |`);
  lines.push(`| average_simulated_latency_ms | ${summary.costLatency.averageLatencyMs} |`);
  lines.push(`| p95_simulated_latency_ms | ${summary.costLatency.p95LatencyMs} |`);
  lines.push(`| failed_cases | ${listOrDash(summary.failedCases)} |`);
  lines.push(`| unstable_cases | ${listOrDash(summary.unstableCases)} |`);
  lines.push("");

  lines.push("## Escalation classification", "");
  lines.push("| TP | FP | TN | FN | Total |", "|---|---|---|---|---|");
  lines.push(
    `| ${summary.escalation.truePositive} | ${summary.escalation.falsePositive} | ${summary.escalation.trueNegative} | ${summary.escalation.falseNegative} | ${summary.escalation.total} |`,
  );
  lines.push("");

  lines.push("## Per-case results", "");
  lines.push(
    "| Case | Risk tags | Expected decision | Outcome pass rate | Trajectory pass rate | Consistent | Decisions seen |",
    "|---|---|---|---|---|---|---|",
  );
  for (const c of report.cases) {
    lines.push(renderCaseRow(c));
  }
  lines.push("");

  const interesting = report.cases.filter(
    (c) =>
      !c.consistency.consistent ||
      c.outcomes.some((o) => !o.passed) ||
      c.trajectories.some((t) => !t.passed),
  );
  if (interesting.length > 0) {
    lines.push("## Failures and instability", "");
    for (const c of interesting) {
      lines.push(renderCaseDetail(c));
    }
  } else {
    lines.push("## Failures and instability", "", "_None — clean run._", "");
  }

  lines.push("## Notes", "");
  lines.push(
    "- All costs/latencies are simulated; no real provider is called.",
    "- `consistency_rate` is the most informative signal for non-deterministic agents:",
    "  it answers _\"if I re-run this same input, does the agent agree with itself?\"_",
    "- Trajectory check enforces required event names appearing in order.",
    "",
  );

  return lines.join("\n");
}

function renderCaseRow(c: CaseEvalReport): string {
  const outcomes = c.outcomes;
  const trajectories = c.trajectories;
  const oPass = outcomes.filter((o) => o.passed).length;
  const tPass = trajectories.filter((t) => t.passed).length;
  const decisions = Object.entries(c.consistency.decisionCounts)
    .map(([d, n]) => `${d}×${n}`)
    .join(", ");
  return `| \`${c.goldenCase.id}\` | ${c.goldenCase.riskTags.join(", ")} | ${c.goldenCase.expectedDecision} | ${oPass}/${outcomes.length} | ${tPass}/${trajectories.length} | ${c.consistency.consistent ? "yes" : "**no**"} | ${decisions} |`;
}

function renderCaseDetail(c: CaseEvalReport): string {
  const lines: string[] = [];
  lines.push(`### \`${c.goldenCase.id}\` — ${c.goldenCase.description}`, "");
  if (!c.consistency.consistent) {
    lines.push(
      `**Inconsistent** across ${c.consistency.totalRuns} runs. Decisions seen: ${JSON.stringify(c.consistency.decisionCounts)}.`,
      "",
    );
  }
  const failedOutcomes = c.outcomes.filter((o) => !o.passed);
  if (failedOutcomes.length > 0) {
    lines.push("**Failed outcomes**:", "");
    for (const o of failedOutcomes) {
      lines.push(
        `- attempt ${o.attempt}: expected \`${o.expectedDecision}\` got \`${o.actualDecision}\` (route: \`${o.actualRoute}\`)`,
      );
    }
    lines.push("");
  }
  const failedTrajectories = c.trajectories.filter((t) => !t.passed);
  if (failedTrajectories.length > 0) {
    lines.push("**Trajectory issues**:", "");
    for (const t of failedTrajectories) {
      lines.push(`- attempt ${t.attempt}: missing events ${JSON.stringify(t.missing)}`);
    }
    lines.push("");
  }
  return lines.join("\n");
}

function pct(r: number): string {
  return `${(r * 100).toFixed(2)}%`;
}

function listOrDash(arr: readonly string[]): string {
  return arr.length === 0 ? "—" : arr.map((s) => `\`${s}\``).join(", ");
}

function titleCase(s: string): string {
  return s.charAt(0).toUpperCase() + s.slice(1);
}
